class CSP:
    def __init__(self, graph, start, goal):
        self.graph = graph
        self.start = start
        self.goal = goal
        self.variables = [node for node in graph.keys()]
        self.domains = {node: list(graph[node]) for node in graph.keys()}
        self.constraints = [(var1, var2) for var1 in graph for var2 in graph[var1] if var2 not in graph]

    def is_consistent(self, assignment):
        # A solution is consistent if we can reach the goal from the start
        path = [assignment[self.start]]
        for node in assignment:
            if node not in path:
                return False
            if node == self.goal:
                return True
            for neighbour in self.graph[node]:
                if neighbour not in path:
                    path.append(neighbour)
                if neighbour == self.goal:
                    return True
        return False

    def backtrack_search(self):
        def search(assignment):
            if sum(assignment.values()) == len(self.variables):
                if self.is_consistent(assignment):
                    return assignment
            for var in self.variables:
                if var not in assignment:
                    for value in self.domains[var]:
                        assignment[var] = value
                        result = search(assignment)
                        if result:
                            return result
                        del assignment[var]
                    return None
        return search({}) if self.backtrack_search() else None

def find_path(graph, start, goal):
    csp = CSP(graph, start, goal)
    solution = csp.backtrack_search()
    return solution.keys() if solution else None

